(function(E){ const x = E["mkt-m1"] = E["mkt-m1"] || {units:{}}; x.units["mkt-3"] = {"grammar":{"id":"c-mkt-3-g","level":"B1","course":"marketing","unit":"mkt-3","title":"Rules in a brief: must, mustn't, don't have to","titleTr":"Brief'teki kurallar: must, mustn't, don't have to","titleFa":"قاعده‌های بریف: must، mustn't، don't have to","formsTable":{"headers":{"en":["Meaning","Say","Example"],"tr":["Anlam","Kullan","Örnek"],"fa":["معنی","بگو","مثال"]},"rows":[["necessary","must / have to","The copy must include the size."],["not allowed","mustn't","You mustn't use the word \"cheap\"."],["not necessary (your choice)","don't have to","You don't have to write the headlines."]]},"wrong":"You don't have to use the word cheap; the client doesn't allow it.","right":"You mustn't use the word cheap; the client doesn't allow it.","blank":{"sentence":"You ___ write the headlines; the editor will do them.","word":"don't have to","distractors":["mustn't","must"]},"wrong2":"The copy must to include the size of each towel.","right2":"The copy must include the size of each towel.","blank2":{"sentence":"The copy ___ include the size of each towel.","word":"must","distractors":["must to","has"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Necessary: must or have to + verb.","tr":"Gerekli: must ya da have to + fiil.","fa":"لازم: must یا have to + فعل.","ex":"The copy must include the size."},{"en":"Not allowed: mustn't + verb.","tr":"Yasak: mustn't + fiil.","fa":"ممنوع: mustn't + فعل.","ex":"You mustn't use the word \"cheap\"."},{"en":"Not necessary, your choice: don't have to + verb.","tr":"Gerekli değil, sana kalmış: don't have to + fiil.","fa":"لازم نیست، به انتخاب خودت: don't have to + فعل.","ex":"You don't have to write the headlines."},{"en":"No to after must and mustn't.","tr":"Must ve mustn't'tan sonra to yok.","fa":"بعد از must و mustn't کلمه‌ی to نمی‌آید.","ex":"must include, not \"must to include\""}],"test":{"en":"Ask: is it forbidden, or just not needed? Forbidden: mustn't. Not needed: don't have to.","tr":"Kendine sor: yasak mı, yoksa sadece gerekli değil mi? Yasaksa mustn't, gerekli değilse don't have to.","fa":"از خودت بپرس: ممنوع است یا فقط لازم نیست؟ ممنوع: mustn't. لازم نیست: don't have to."},"contrast":{"en":"Turkish keeps the two apart (yazmamalısın / yazmak zorunda değilsin), and so does Persian (نباید / لازم نیست). The trap is in English: mustn't and don't have to look like twins.","tr":"Türkçe bu ikisini ayırır: \"yazmamalısın\" (mustn't) ve \"yazmak zorunda değilsin\" (don't have to). Tuzak İngilizcede: mustn't ile don't have to ikiz gibi görünür ama değildir.","fa":"فارسی این دو را از هم جدا می‌کند: «نباید بنویسی» (mustn't) و «لازم نیست بنویسی» (don't have to). تله در انگلیسی است: mustn't و don't have to شبیه دوقلوها به نظر می‌رسند، ولی نیستند."}},"errorWatch":[{"find":["must to","mustn't to","must not to","have not to"],"fix":{"en":"After must and mustn't, use the base verb with no to: \"must include\". For \"not necessary\", say \"don't have to\".","tr":"Must ve mustn't'tan sonra to olmadan yalın fiil kullan: \"must include\". \"Gerekli değil\" için \"don't have to\" de.","fa":"بعد از must و mustn't فعل ساده بدون to بیاور: «must include». برای «لازم نیست» بگو «don't have to»."}}]},"b2":{"id":"c-mkt-3-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-3","title":"Formal brief language: is to, is expected to, is intended to","titleTr":"Resmî brief dili: is to, is expected to, is intended to","titleFa":"زبان رسمی بریف: is to، is expected to، is intended to","formsTable":{"headers":{"en":["Form","Use","Example"],"tr":["Yapı","Kullanım","Örnek"],"fa":["ساختار","کاربرد","مثال"]},"rows":[["is to (be done)","instruction or plan","The copy is to be delivered by 10 November."],["is expected to","what someone should do","The writer is expected to submit two options."],["is intended to","purpose","The page is intended to explain the product."]]},"wrong":"The copy is to deliver by 10 November.","right":"The copy is to be delivered by 10 November.","blank":{"sentence":"All three descriptions are to ___ by 10 November.","word":"be delivered","distractors":["deliver","delivering"]},"wrong2":"The writer is expected submitting two options.","right2":"The writer is expected to submit two options.","blank2":{"sentence":"The writer is expected ___ two options for each product.","word":"to submit","distractors":["submitting","submit"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Instruction or plan: be to + verb.","tr":"Talimat ya da plan: be to + fiil.","fa":"دستور یا برنامه: be to + فعل.","ex":"The copy is to be delivered by Friday."},{"en":"What someone should do: be expected to + verb.","tr":"Birinin ne yapması gerektiği: be expected to + fiil.","fa":"کاری که کسی باید بکند: be expected to + فعل.","ex":"The writer is expected to submit two options."},{"en":"Purpose: be intended to + verb.","tr":"Amaç: be intended to + fiil.","fa":"هدف: be intended to + فعل.","ex":"The page is intended to explain the product."}],"test":{"en":"Does the subject do the action? Use to + verb. Is the action done to it? Use to be + past participle.","tr":"İşi özne mi yapıyor? to + fiil kullan. İş özneye mi yapılıyor? to be + üçüncü hâl kullan.","fa":"فاعل خودش کار را می‌کند؟ to + فعل. کار روی فاعل انجام می‌شود؟ to be + اسم مفعول."},"contrast":{"en":"Turkish says \"teslim edilecek\" or \"...ması bekleniyor\", and Persian «قرار است تحویل داده شود» or «انتظار می‌رود». English adds to + verb, or to be + past participle when the subject receives the action.","tr":"Türkçede \"teslim edilecek\" ya da \"...ması bekleniyor\" deriz. İngilizcede bunlar to + fiil ile, özne işi almıyorsa to be + üçüncü hâl ile kurulur.","fa":"در فارسی می‌گوییم «قرار است تحویل داده شود» یا «انتظار می‌رود...». انگلیسی to + فعل می‌آورد، و وقتی کار روی فاعل انجام می‌شود to be + اسم مفعول."}},"errorWatch":[{"find":["copy is to deliver","descriptions are to deliver","photos are to deliver","is expected submitting","are expected submitting","is intended showing","is intended explaining"],"fix":{"en":"Use to + verb after these forms (\"is expected to submit\"), and to be + past participle when the subject receives the action (\"is to be delivered\").","tr":"Bu yapılardan sonra to + fiil kullan (\"is expected to submit\"); özne işi almıyorsa to be + üçüncü hâl (\"is to be delivered\").","fa":"بعد از این ساختارها to + فعل بیاور («is expected to submit»)، و وقتی کار روی فاعل انجام می‌شود to be + اسم مفعول («is to be delivered»)."}}],"useIn":{"en":"B2: in your brief, use is to, is expected to or is intended to at least once.","tr":"B2: brief'inde is to, is expected to ya da is intended to yapısını en az bir kez kullan.","fa":"B2: در بریفت دست‌کم یک بار is to یا is expected to یا is intended to به کار ببر."},"exitItem":{"from":"mkt-3","kind":"blank","prompt":"The new photos are intended ___ how soft the towels are.","options":["showing","to show","show"],"correct":1}},"vocab":{"id":"c-mkt-3-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-3","goals":["career"],"title":{"en":"The Brief","tr":"Brief","fa":"بریف"},"cards":[{"word":"brief","sentence":"The writer needs a clear brief before she can start.","meaning":{"en":"A short document that tells someone exactly what to make.","tr":"brief (işin tarifini veren kısa belge)","fa":"بریف (شرح کوتاه سفارش کار)"}},{"word":"objective","sentence":"The objective is to sell 500 towels in the first month.","meaning":{"en":"What a piece of work must achieve.","tr":"amaç, hedef","fa":"هدف"}},{"word":"deliverable","sentence":"There are three deliverables: one description for each product.","gap":"deliverables","accept":["deliverables","deliverable"],"meaning":{"en":"A finished piece of work that someone must hand over.","tr":"teslim edilecek iş","fa":"خروجی قابل‌تحویل"}},{"word":"deadline","sentence":"The deadline for the first draft is 10 November.","meaning":{"en":"The day or time by which work must be finished.","tr":"son teslim tarihi","fa":"مهلت تحویل؛ ددلاین"}},{"word":"budget","sentence":"The budget for the copy is 900 pounds.","meaning":{"en":"The money you can spend on something.","tr":"bütçe","fa":"بودجه"}},{"word":"tone of voice","sentence":"Our tone of voice is warm and simple, never pushy.","meaning":{"en":"The way a brand sounds when it writes or speaks.","tr":"marka dili, iletişim tonu","fa":"لحن برند"}},{"word":"key message","sentence":"A good key message fits in one line.","meaning":{"en":"The one idea the reader must remember.","tr":"ana mesaj","fa":"پیام اصلی"}},{"word":"call to action","sentence":"End the page with a clear call to action, such as \"Find your colour\".","meaning":{"en":"Words that tell the reader what to do next.","tr":"harekete geçirici mesaj (CTA)","fa":"دعوت به اقدام (CTA)"}},{"word":"sign off","sentence":"The manager has to sign off the final copy before it goes online.","meaning":{"en":"To give final approval to a piece of work.","tr":"son onayı vermek","fa":"تأیید نهایی دادن"}},{"word":"word count","sentence":"The word count for each description is 80 to 100.","meaning":{"en":"How many words a text has, or should have.","tr":"kelime sayısı","fa":"تعداد کلمه"}}]},"judge":{"id":"c-mkt-3-j","course":"marketing","unit":"mkt-3","type":"judge","title":{"en":"Can a writer act on it?","tr":"Yazar bununla işe başlayabilir mi?","fa":"نویسنده می‌تواند با این کار کند؟"},"prompt":"Four lines from briefs for a running app's email campaign.","parts":["Clear","Specific","The writer can act on it"],"instruction":{"en":"Tap what each line does well. A good brief line has all three.","tr":"Her satırın iyi yaptığı şeylere dokun. İyi bir brief satırında üçü de vardır.","fa":"روی کارهای خوبی که هر خط کرده بزن. خط خوب یک بریف هر سه را دارد."},"items":[{"by":"AI tool","answer":"Create engaging, viral content that elevates the brand.","present":[],"fix":{"en":"Nobody can act on \"engaging\" or \"elevates\". Say what to write and for whom: \"Three emails for new runners who gave up.\"","tr":"\"Engaging\" ya da \"elevates\" ile kimse işe başlayamaz. Ne yazılacağını ve kimin için olduğunu söyle: \"Three emails for new runners who gave up.\"","fa":"با «engaging» یا «elevates» کسی نمی‌تواند کاری بکند. بگو چه چیزی و برای که نوشته شود: «Three emails for new runners who gave up.»"}},{"by":"AI tool","answer":"Target all audiences across all markets.","present":["Clear"],"fix":{"en":"Clear, but \"all audiences\" means no audience. Name one reader.","tr":"Açık, ama \"all audiences\" hiçbir kitle demektir. Tek bir okur söyle.","fa":"روشن است، ولی «all audiences» یعنی هیچ مخاطبی. یک خواننده را نام ببر."}},{"by":"Good model","answer":"Must not: the word \"easy\", or any health claim we can't prove.","present":["Clear","Specific","The writer can act on it"],"fix":null},{"by":"Marketing manager","answer":"The tone should be premium, modern and authentic.","present":[],"fix":{"en":"Three adjectives that every brand uses. Describe the voice with an example, or attach your voice sheet.","tr":"Her markanın kullandığı üç sıfat. Sesi bir örnekle anlat ya da marka sesi sayfanı ekle.","fa":"سه صفتی که همه‌ی برندها می‌گویند. صدا را با یک مثال توصیف کن یا برگه‌ی صدای برند را ضمیمه کن."}}]},"writing":{"id":"c-mkt-3-w","title":{"en":"A creative brief","tr":"Bir kreatif brief","fa":"یک بریف خلاقانه"},"course":"marketing","unit":"mkt-3","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"mkt-final-1","prompt":{"en":"Write a brief (80-110 words) for your own next piece of content, or from these notes on a running app: three emails; goal 500 trial sign-ups; readers: new runners who gave up after a week; message: your first 5K, ten minutes a day; must include the free trial and a real plan; no health claims; never say \"easy\"; by 10 May. Use the six headings: Objective, Audience, Key message, Must include, Must not, Deliverables and deadline.","tr":"Kendi bir sonraki içeriğin için ya da bir koşu uygulamasının şu notlarından brief yaz (80-110 kelime): üç e-posta; hedef 500 deneme kaydı; okurlar: bir hafta sonra bırakan yeni koşucular; mesaj: your first 5K, ten minutes a day; ücretsiz deneme ve gerçek bir plan yer almalı; sağlık iddiası yok; \"easy\" kelimesi yok; 10 Mayıs'a kadar. Altı başlığı kullan: Objective, Audience, Key message, Must include, Must not, Deliverables and deadline.","fa":"برای محتوای بعدی خودت یا از روی این یادداشت‌های یک اپلیکیشن دویدن بریف بنویس (۸۰ تا ۱۱۰ کلمه): سه ایمیل؛ هدف ۵۰۰ ثبت‌نام آزمایشی؛ خواننده‌ها: دونده‌های تازه‌کاری که بعد از یک هفته ول کردند؛ پیام: your first 5K, ten minutes a day؛ دوره‌ی آزمایشی رایگان و یک برنامه‌ی واقعی باید بیاید؛ بدون ادعای سلامتی؛ کلمه‌ی «easy» نیاید؛ تا ۱۰ مه. شش تیتر را به کار ببر: Objective، Audience، Key message، Must include، Must not، Deliverables and deadline."},"model":"Objective: 500 trial sign-ups from three emails.\nAudience: new runners who gave up after a week. They think running is not for them.\nKey message: your first 5K, ten minutes a day.\nMust include: the free trial; the real ten-minute plan; one real user question.\nMust not: the word \"easy\", or any health claim we can't prove.\nDeliverables and deadline: three emails, 80-100 words each, by 10 May. You must send a first draft of email 1 by 3 May. You don't have to write the subject lines.","frame":"Objective: ___.\nAudience: ___.\nKey message: ___.\nMust include: ___.\nMust not: ___.\nDeliverables and deadline: ___, by ___. You must ___. You don't have to ___.","words":[{"word":"must"},{"word":"don't have to"},{"word":"deadline"}],"minWords":80,"minSentences":6,"rubric":["Task done: all six parts, one key message","Organised: one heading per part, short lines","Language: must, mustn't and don't have to with the right meaning","Tone: clear and friendly; nothing a writer has to guess"],"rubricI18n":{"tr":["Görev: altı bölümün hepsi, tek ana mesaj","Düzen: her bölüm için bir başlık, kısa satırlar","Dil: must, mustn't ve don't have to doğru anlamıyla","Üslup: açık ve samimi; yazarın tahmin edeceği bir şey yok"],"fa":["کامل بودن کار: هر شش بخش، یک پیام اصلی","نظم: برای هر بخش یک تیتر، خط‌های کوتاه","زبان: must، mustn't و don't have to با معنای درست","لحن: روشن و دوستانه؛ چیزی نمانده که نویسنده حدس بزند"]}},"speaking":{"id":"mkt-3","course":"marketing","unit":"mkt-3","topic":{"en":"Explaining a brief on a call","tr":"Bir brief'i telefonda anlatmak","fa":"توضیح بریف در تماس"},"warmup":{"en":"Think of a task someone explained badly to you. What was missing?","tr":"Birinin sana kötü anlattığı bir işi düşün. Ne eksikti?","fa":"به کاری فکر کن که کسی بد برایت توضیح داده. چه چیزی کم بود؟"},"questions":[{"en":"Explain a job to a freelance writer: what, for whom and by when.","tr":"Serbest çalışan bir yazara işi anlat: ne, kimin için, ne zamana kadar.","fa":"یک کار را برای نویسنده‌ی فریلنس توضیح بده: چه چیزی، برای که، تا کی."},{"en":"Say one thing the writer must include and one thing they mustn't do.","tr":"Yazarın mutlaka eklemesi gereken bir şeyi ve yapmaması gereken bir şeyi söyle.","fa":"یک چیزی را که نویسنده باید بیاورد و یک کاری را که نباید بکند بگو."},{"en":"The writer asks: \"Do I need to write the headlines too?\" Answer.","tr":"Yazar soruyor: \"Do I need to write the headlines too?\" Cevap ver.","fa":"نویسنده می‌پرسد: «Do I need to write the headlines too?» جواب بده."}],"followups":[{"en":"Now explain a real task from your own work in under a minute.","tr":"Şimdi kendi işinden gerçek bir görevi bir dakikadan kısa sürede anlat.","fa":"حالا یک کار واقعی از کار خودت را در کمتر از یک دقیقه توضیح بده."}],"expressions":[{"phrase":"The main thing is...","meaning":{"en":"Gives the key message first.","tr":"Önce ana mesajı verir.","fa":"اول پیام اصلی را می‌گوید."}},{"phrase":"We'd rather not...","meaning":{"en":"A soft way to say \"you mustn't\".","tr":"\"You mustn't\" demenin yumuşak yolu.","fa":"راه نرم‌تر برای گفتن «you mustn't»."}},{"phrase":"You don't have to...","meaning":{"en":"Says what is not necessary.","tr":"Neyin gerekli olmadığını söyler.","fa":"می‌گوید چه چیزی لازم نیست."}}],"model":"Thanks for taking this on. The main thing is one message: your first 5K, ten minutes a day. It's three emails, about a hundred words each, for new runners who gave up. We need them by 10 May. You must include the free trial. We'd rather not use the word easy, because it isn't. You don't have to write the subject lines; our editor will.","selfCheck":[{"en":"I said what, for whom and by when.","tr":"Ne, kimin için ve ne zamana kadar olduğunu söyledim.","fa":"گفتم چه چیزی، برای که و تا کی."},{"en":"I gave one key message.","tr":"Tek bir ana mesaj verdim.","fa":"یک پیام اصلی گفتم."},{"en":"I used mustn't and don't have to correctly.","tr":"mustn't ve don't have to'yu doğru kullandım.","fa":"mustn't و don't have to را درست به کار بردم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم در زمانش تمام شد."}]},"exit":{"id":"c-mkt-3-x","course":"marketing","unit":"mkt-3","type":"exit","items":[{"from":"mkt-3","kind":"blank","prompt":"You ___ bring samples to the meeting; we already have them.","options":["mustn't","must","don't have to"],"correct":2,"point":2},{"from":"mkt-3","kind":"mcq","prompt":"Which brief line can a writer act on?","options":["Make it pop.","Write 80-100 words for UK online shoppers.","Be creative and fresh."],"correct":1,"point":1},{"from":"mkt-3","kind":"mcq","prompt":"Which part of a brief is missing here? \"Three emails for new runners, by 10 May.\"","options":["The deadline","The audience","The key message"],"correct":2,"point":1},{"from":"mkt-2","kind":"blank","prompt":"About half ___ the respondents shop online every week.","options":["from","of","in"],"correct":1},{"from":"mkt-2","kind":"mcq","prompt":"Which reader-card line is based on data?","options":["In our survey, 40% had used the product before.","She loves a modern lifestyle.","Young people like new things."],"correct":0},{"from":"mkt-1","kind":"blank","prompt":"In the old days we ___ sell only in shops; now we also sell online.","options":["use to","used to","are used to"],"correct":1}]},"explain":{"id":"c-mkt-3-e","course":"marketing","unit":"mkt-3","type":"explain","level":"B1","title":{"en":"A brief that gets good copy","tr":"İyi metin getiren brief","fa":"بریفی که متن خوب می‌آورد"},"objective":{"en":"In this lesson you will learn to write a creative brief with six clear parts.","tr":"Bu derste altı net bölümden oluşan bir kreatif brief yazmayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک بریف خلاقانه با شش بخش روشن بنویسی."},"hook":{"en":"A weak brief gets weak copy, from a writer or from an AI tool. Six short parts fix most of it.","tr":"Zayıf brief zayıf metin getirir; yazan ister insan ister yapay zekâ olsun. Altı kısa bölüm bunun çoğunu çözer.","fa":"بریف ضعیف متن ضعیف می‌آورد، چه از نویسنده چه از هوش مصنوعی. شش بخش کوتاه بیشترش را حل می‌کند."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"The six parts of a brief","tr":"Brief'in altı bölümü","fa":"شش بخش یک بریف"},"steps":[{"en":"Objective and audience: what must this piece do, and for which reader?","tr":"Hedef ve kitle: bu metin ne yapmalı, hangi okur için?","fa":"هدف و مخاطب: این متن باید چه کاری بکند، برای کدام خواننده؟","ex":"Objective: 500 trial sign-ups. Audience: new runners who gave up."},{"en":"Key message: one sentence. If you have three, choose one.","tr":"Ana mesaj: tek cümle. Üç tane varsa birini seç.","fa":"پیام اصلی: یک جمله. اگر سه تا داری، یکی را انتخاب کن.","ex":"Your first 5K, ten minutes a day."},{"en":"Must include and must not: facts, proof, words to avoid.","tr":"Olması ve olmaması gerekenler: gerçekler, kanıtlar, kaçınılacak kelimeler.","fa":"حتماً بیاید و نیاید: واقعیت‌ها، مدرک‌ها، کلمه‌هایی که نباید بیایند.","ex":"Must not: the word easy, or any health claim we can't prove."},{"en":"Deliverables and deadline: what, how long, by when.","tr":"Teslim edilecekler ve son tarih: ne, ne uzunlukta, ne zamana kadar.","fa":"تحویلی‌ها و مهلت: چه چیزی، چقدر، تا کی.","ex":"Three emails, 80-100 words each, by 10 May."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Rules in a brief: must, mustn't, don't have to","tr":"Brief'teki kurallar: must, mustn't, don't have to","fa":"قاعده‌های بریف: must، mustn't، don't have to"},"steps":[{"en":"Necessary: must or have to + verb.","tr":"Gerekli: must ya da have to + fiil.","fa":"لازم: must یا have to + فعل.","ex":"The copy must include the size."},{"en":"Not allowed: mustn't + verb.","tr":"Yasak: mustn't + fiil.","fa":"ممنوع: mustn't + فعل.","ex":"You mustn't use the word \"cheap\"."},{"en":"Not necessary, your choice: don't have to + verb.","tr":"Gerekli değil, sana kalmış: don't have to + fiil.","fa":"لازم نیست، به انتخاب خودت: don't have to + فعل.","ex":"You don't have to write the headlines."},{"en":"No to after must and mustn't.","tr":"Must ve mustn't'tan sonra to yok.","fa":"بعد از must و mustn't کلمه‌ی to نمی‌آید.","ex":"must include, not \"must to include\""}],"table":{"headers":{"en":["Meaning","Say","Example"],"tr":["Anlam","Kullan","Örnek"],"fa":["معنی","بگو","مثال"]},"rows":[["necessary","must / have to","The copy must include the size."],["not allowed","mustn't","You mustn't use the word \"cheap\"."],["not necessary (your choice)","don't have to","You don't have to write the headlines."]]},"tip":{"en":"Turkish keeps the two apart (yazmamalısın / yazmak zorunda değilsin), and so does Persian (نباید / لازم نیست). The trap is in English: mustn't and don't have to look like twins.","tr":"Türkçe bu ikisini ayırır: \"yazmamalısın\" (mustn't) ve \"yazmak zorunda değilsin\" (don't have to). Tuzak İngilizcede: mustn't ile don't have to ikiz gibi görünür ama değildir.","fa":"فارسی این دو را از هم جدا می‌کند: «نباید بنویسی» (mustn't) و «لازم نیست بنویسی» (don't have to). تله در انگلیسی است: mustn't و don't have to شبیه دوقلوها به نظر می‌رسند، ولی نیستند."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"The same brief works for an AI tool","tr":"Aynı brief yapay zekâ aracı için de işe yarar","fa":"همین بریف برای ابزار هوش مصنوعی هم جواب می‌دهد"},"body":{"en":"Paste the six parts into your prompt, with your voice sheet. On a call, British colleagues often soften the rules: \"We'd rather not mention the price.\" In writing, short rules are normal and clear.","tr":"Altı bölümü, marka sesi sayfanla birlikte komutuna yapıştır. Görüşmede İngiliz iş arkadaşları kuralları çoğu zaman yumuşatır: \"We'd rather not mention the price.\" Yazılı metinde kısa kurallar normal ve açıktır.","fa":"شش بخش را همراه برگه‌ی صدای برند در پرامپتت بچسبان. در تماس تلفنی، همکاران بریتانیایی معمولاً قاعده را نرم‌تر می‌گویند: «We'd rather not mention the price.» در متن نوشتاری، قاعده‌های کوتاه عادی و روشن‌اند."},"phrases":[{"phrase":"The main thing is...","meaning":{"en":"Gives the key message first.","tr":"Önce ana mesajı verir.","fa":"اول پیام اصلی را می‌گوید."}},{"phrase":"We'd rather not...","meaning":{"en":"A soft way to say \"you mustn't\".","tr":"\"You mustn't\" demenin yumuşak yolu.","fa":"راه نرم‌تر برای گفتن «you mustn't»."}},{"phrase":"You don't have to...","meaning":{"en":"Says what is not necessary.","tr":"Neyin gerekli olmadığını söyler.","fa":"می‌گوید چه چیزی لازم نیست."}},{"phrase":"key message","meaning":{"en":"The one idea the reader must remember.","tr":"ana mesaj","fa":"پیام اصلی"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Rewrite a useless brief","tr":"İşe yaramayan bir brief'i yeniden yaz","fa":"یک بریف بی‌فایده را بازنویسی کن"},"item":"Create engaging, viral content that elevates the brand across all markets.","answer":"Three emails for new runners who gave up, 80-100 words each, by 10 May. Key message: your first 5K, ten minutes a day.","walk":[{"en":"Find what the writer can't act on: engaging, viral, elevates.","tr":"Yazarın harekete geçemeyeceği kelimeleri bul: engaging, viral, elevates.","fa":"کلمه‌هایی را پیدا کن که نویسنده با آن‌ها کاری نمی‌تواند بکند: engaging، viral، elevates."},{"en":"Answer the missing questions: what, for whom, how long, by when?","tr":"Eksik soruları cevapla: ne, kimin için, ne uzunlukta, ne zamana kadar?","fa":"سؤال‌های جامانده را جواب بده: چه چیزی، برای که، چقدر، تا کی؟"},{"en":"Add the one message the reader must take away.","tr":"Okurun aklında kalması gereken tek mesajı ekle.","fa":"همان یک پیامی را که باید در ذهن خواننده بماند اضافه کن."}]},"quick":{"prompt":"A good brief has one ___, not three.","options":["key message","reader question","deadline reminder"],"correct":0,"why":{"en":"key message: when a piece tries to say three things, the reader remembers none of them.","tr":"key message: bir metin üç şey söylemeye çalışınca okur hiçbirini hatırlamaz.","fa":"key message: وقتی متنی می‌خواهد سه چیز بگوید، خواننده هیچ‌کدام را به یاد نمی‌سپارد."}},"remember":{"en":"Could a stranger start work from this brief today? If not, what is missing?","tr":"Bir yabancı bu brief'le bugün işe başlayabilir mi? Başlayamıyorsa ne eksik?","fa":"یک غریبه می‌تواند با این بریف همین امروز شروع کند؟ اگر نه، چه چیزی کم است؟"},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Formal brief language: is to, is expected to, is intended to","tr":"Resmî brief dili: is to, is expected to, is intended to","fa":"زبان رسمی بریف: is to، is expected to، is intended to"},"steps":[{"en":"Instruction or plan: be to + verb.","tr":"Talimat ya da plan: be to + fiil.","fa":"دستور یا برنامه: be to + فعل.","ex":"The copy is to be delivered by Friday."},{"en":"What someone should do: be expected to + verb.","tr":"Birinin ne yapması gerektiği: be expected to + fiil.","fa":"کاری که کسی باید بکند: be expected to + فعل.","ex":"The writer is expected to submit two options."},{"en":"Purpose: be intended to + verb.","tr":"Amaç: be intended to + fiil.","fa":"هدف: be intended to + فعل.","ex":"The page is intended to explain the product."}],"table":{"headers":{"en":["Form","Use","Example"],"tr":["Yapı","Kullanım","Örnek"],"fa":["ساختار","کاربرد","مثال"]},"rows":[["is to (be done)","instruction or plan","The copy is to be delivered by 10 November."],["is expected to","what someone should do","The writer is expected to submit two options."],["is intended to","purpose","The page is intended to explain the product."]]},"body":{"en":"B2: in your brief, use is to, is expected to or is intended to at least once.","tr":"B2: brief'inde is to, is expected to ya da is intended to yapısını en az bir kez kullan.","fa":"B2: در بریفت دست‌کم یک بار is to یا is expected to یا is intended to به کار ببر."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
